using System;using System.IO;using Emberfall;
public static class ConcentratedVenomPersistenceTests{
 static int n;static void Check(bool ok,string s){n++;if(!ok)throw new Exception(s);}
 public static string Run(string root){var p=new ProgressionService(Path.Combine(root,"venom"));Check(p.CreateNewSlot(HeroClass.Ranger),"create sword save");p.Profile.level=20;p.Profile.mechanicMaterials=40;p.Profile.gold=100000;p.Profile.bestFloor=5;p.Save();var item=p.CreateMechanicItem(EquipmentMechanic.VenomSpread);Check(p.CollectLoot(item)&&p.Equip(item.id),"collect actual mechanism");string id=item.id;Check(p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==0,"legacy defaultA");Check(!p.ToggleMechanicVariant(id,false),"camp required");string snapshot=UnityEngine.JsonUtility.ToJson(p.Profile,false);Directory.CreateDirectory(p.SaveFilePath+".tmp");Check(!p.ToggleMechanicVariant(id,true)&&UnityEngine.JsonUtility.ToJson(p.Profile,false)==snapshot,"failed unlock atomic");Directory.Delete(p.SaveFilePath+".tmp");Check(p.ToggleMechanicVariant(id,true)&&p.Profile.mechanicMaterials==36,"firstB unlock four shards");Check(p.Profile.inventory.Find(x=>x.id==id).mechanicVariantUnlocked&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"selectedB survives transaction validation");Check(p.SaveBuildPreset(0,true),"captureB build");Check(p.ToggleMechanicVariant(id,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==0&&p.Profile.mechanicMaterials==36,"A toggle free");Check(p.ApplyBuildPreset(0,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"actual build apply restoresB");Check(p.LoadSlot(p.CurrentSlotId)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"reload retainsB");Check(p.AscendMechanic(id,true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1&&p.Profile.inventory.Find(x=>x.id==id).rarity==Rarity.Legendary,"ascension retainsB");p.Profile.level=30;p.Save();Check(p.ReforgeMechanic(p.QuoteReforge(id,25),true)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"reforge retainsB");Check(p.LoadSlot(p.CurrentSlotId)&&p.Profile.inventory.Find(x=>x.id==id).level==25&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==1,"reforged reload retainsB");p.Profile.inventory.Find(x=>x.id==id).mechanicVariantUnlocked=false;p.Profile.inventory.Find(x=>x.id==id).mechanicVariant=1;p.Save();Check(p.LoadSlot(p.CurrentSlotId)&&p.Profile.inventory.Find(x=>x.id==id).mechanicVariant==0,"locked forgedB sanitizesA");return "PASS "+n+" actual variant unlock/build/save/ascension/reforge assertions";}}
